void canbusoff(byte num,float Min_tBusOffQuick,float Max_tBusOffQuick,float Min_tBusOffSlow,float Max_tBusOffSlow)
{
  long result;
  dword index = 0,i;
  float Eventtime;
  xcpDisconnect("XCPDemo");
  canConfigureBusOff(1,TxMessageId[0], 1);
    for(i=0;i<=num*32;i++)
    {
      result = TestJoinTextEvent("ErrorFrame occurred 11F");
      index = TestWaitForAnyJoinedEvent(2000);
      Eventtime = TestGetLastWaitElapsedTimeNS()/1000000;
      if(i%32 == 0 && i/32 <num && i>0)
      {
        if(Eventtime > Min_tBusOffQuick && Eventtime < Max_tBusOffQuick)
        {testStepPass("BusOff 快恢复时间","tBusOffQuick = %f",Eventtime);}
        else
        {testStepFail("BusOff 快恢复时间","tBusOffQuick = %f",Eventtime);}
        writeex(-3,0,"quick  %d  %f",i,TestGetLastWaitElapsedTimeNS()/1000000);
      }
      if(i%32 == 0 && i/32 == num)
      {
        if(Eventtime > Min_tBusOffSlow && Eventtime < Max_tBusOffSlow)
        {testStepPass("BusOff 慢恢复时间","tBusOffSlow = %f",Eventtime);}
        else
        {testStepFail("BusOff 慢恢复时间","tBusOffSlow = %f",Eventtime);}        
        writeex(-3,0,"slow  %d  %f",i,TestGetLastWaitElapsedTimeNS()/1000000);
      }      
      if(index==0)
      {
        break;
      }
    }
  canConfigureBusOff(1,TxMessageId[0], 0);   
}

byte ReadExtend(dword DTC,byte DTCstate)
{
    int retVal,i;    
    byte retSize ;
    word ResDTC;
    diagRequest  *  diagReq;
    diagSetTarget ("ABS_ESP");

    // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
    diagResize(diagReq,6);
    DiagSetPrimitiveByte(diagReq,0,0x19);
    DiagSetPrimitiveByte(diagReq,1,0x04);
    DiagSetPrimitiveByte(diagReq,2,DTC>>16); 
    DiagSetPrimitiveByte(diagReq,3,DTC>>8&0xFF); 
    DiagSetPrimitiveByte(diagReq,4,DTC&0xFF);  
    DiagSetPrimitiveByte(diagReq,5,0x21); 

    //send and wait response
    TestReportWriteDiagObject(diagReq);    
    DiagSendRequest(diagReq);
    TestWaitForDiagRequestSent(diagReq, 150);    
    retVal = TestWaitForDiagResponse(diagReq, 1000);    //Get last response
    TestReportWriteDiagResponse(diagReq);   // write response to report
    retSize=DiagGetRespPrimitiveSize(diagReq);
  //write("***************retVal:%d",retVal);

    if(retVal != 1)
    {
      testStepFail("读取快照","Response Code is %d",retVal);
    }     
  if(DTCstate==1)
  {
    if(retSize>6)
     {TestSteppass("读取快照","有快照信息");}
    else 
     {testStepFail("读取快照","没有快照信息");}  
  }
  else
  {
     if(retSize>6)
     {testStepFail("读取快照","没有快照信息");}
    else 
     {TestSteppass("读取快照","有快照信息");}  
  }
  return retSize;
}

byte ReadExtend(dword DTC,dword DID,qword DID1)
{
    int retVal,i;    
    byte retSize ;
    word ResDTC;
    dword value;
    diagRequest  *  diagReq;
    diagSetTarget ("ABS_ESP");

    // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
    diagResize(diagReq,6);
    DiagSetPrimitiveByte(diagReq,0,0x19);
    DiagSetPrimitiveByte(diagReq,1,0x04);
    DiagSetPrimitiveByte(diagReq,2,DTC>>16); 
    DiagSetPrimitiveByte(diagReq,3,DTC>>8&0xFF); 
    DiagSetPrimitiveByte(diagReq,4,DTC&0xFF);  
    DiagSetPrimitiveByte(diagReq,5,0xff); 

    //send and wait response
    TestReportWriteDiagObject(diagReq);    
    DiagSendRequest(diagReq);
    TestWaitForDiagRequestSent(diagReq, 150);    
    retVal = TestWaitForDiagResponse(diagReq, 1000);    //Get last response
    TestReportWriteDiagResponse(diagReq);   // write response to report
    retSize=DiagGetRespPrimitiveSize(diagReq);
    //write("***************retVal:%X",DTC);

   while(1)
  { int ii=0;

   if(DiagGetRespPrimitiveByte(diagReq,ii)==DID>>8
    &&DiagGetRespPrimitiveByte(diagReq,ii+1)==DID&0xFF)
  {
    DID=DiagGetRespPrimitiveByte(diagReq,ii+2)<<8|DiagGetRespPrimitiveByte(diagReq,ii+3);
  }
   if(DiagGetRespPrimitiveByte(diagReq,ii)==DID1>>8
    &&DiagGetRespPrimitiveByte(diagReq,ii+1)==DID1&0xFF)
  { DID1=0;
    for(i=0;i<6;i++)
    { 
      DID1=DID1 << 8|DiagGetRespPrimitiveByte(diagReq,ii+2+i);
    }

  }   
  ii++;
  if(ii==retSize)
  {
    break;
  }
  }

  return retSize;
}

