/// <Bus>
_Signal_discontinuity_invalid(dword aId,int Cycle,signal *sig,int def, int sum,dword DTC)//信号有效位无效
{ 
  if(DTC)
  {  
    if(sum>=3)
    {
    testEnableMsg(aId);
    Req14();//清故障
    testWaitForTimeout(1000);

    testStep("错误推测","信号有效位为%d不连续无效超过%dms应不记录故障",def,Cycle*(sum));

    {
      int i;
      i=0;
      while(1)
      {
        setSignal(sig,def); //**********设置信号有效位无效
        writeex(-3,0,"信号有效位为%d无效%dms",def,Cycle*(2));
        _cntrset(aId,2,Cycle);
        i+=2;
        if(i>sum)
        {
          break;
        }
        testResetSignalValue(sig);//**********
        writeex(-3,0,"信号有效位为%d恢复%dms",def,Cycle*(2));
        _cntrset(aId,2,Cycle);        
      }
    }     

    TestStep_ReadDTC("诊断",DTC,9,0,0,1);//诊断故障,应无故障
    testResetSignalValue(sig);//**********

  }else
    {
     testSteppass("不连续成熟", "成熟次数小于3,无法测试不连续成熟");
    }
  }
}
