  if(DTC)
  {  
    if(rec<=1)
    {
      testStep("无效恢复检测","无效位为%d无效恢复%dms应记录故障",1,Cycle*rec);
     //testWaitForTimeout(Cycle*rec);
      _cntrset(aId,rec,Cycle);
     //setSignal(Value,1);//**********
      testDisableMsg(aId);
      TestStep_ReadDTC("诊断",DTC,1,0,0,1);
      testResetSignalValue(Value); 
      testenableMsg(aId);
    }
    else
    { 
      testStep("无效恢复检测","无效位为%d无效恢复%dms应记录故障",1,Cycle*(rec-1));
      //testWaitForTimeout(Cycle*(rec-1));
