      setSignal(Value,def);//**********
      //testWaitForTimeout(Cycle);
      TestStep_ReadDTC("诊断",DTC,1,0,1,1);

      testWaitForTimeout(Cycle*(sum+1));//等待
      testStep("无效恢复检测","有效位为%d无效%dms应记录故障",1,Cycle*(rec+1));
      testResetSignalValue(Value);
      //testWaitForTimeout(Cycle*(rec+1));
      _cntrset(aId,rec+1,Cycle);
      testDisableMsg(aId);
      TestStep_ReadDTC("诊断",DTC,1,0,0,1);
      testResetSignalValue(Value); 
     testWaitForTimeout(1000);
    }
  }
  msgswitch(aId,1); 
}
