/// <Diag>
_testDTC(dword DTC,byte diag,byte sate)//单故障码诊断  diag:1-当前故障；9-历史故障,sate：1-查询有无DTC；0-查询是否只有DTC
{
  diagRequest  *  req1902;
  diagSetTarget ("ABS_ESP");

  // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
  diagResize(req1902,3);
  DiagSetPrimitiveByte(req1902,0,0x19);
  DiagSetPrimitiveByte(req1902,1,0x02);
  DiagsetPrimitiveByte(req1902,2,diag);
  diagSendRequest(req1902);
  testReportWriteDiagObject(req1902);
  testWaitForDiagResponse(req1902,5000);
