    for(i=0;i<(size-3);i++)
    {
      buffer[i]=DiagGetRespPrimitiveByte(req1902,i+3);
    }
    size=(size-3)/4;

    for(i=0;i<size;i++)
    {
      DTCread[i]=(buffer[i*4]<<16)|(buffer[i*4+1]<<8)|buffer[i*4+2];
    }
    if((DTC==0))
      {
        if(size>0)
        {testStepFail("诊断故障码","获取到的故障码不合法");}
        if(!sate)
        {
          for(i=0;i<size;i++)
           {
           if(DTCread[i]==DTC)
            {
             } else{testStepFail("诊断故障码","获取到的故障码不合法0x%06X",DTCread[i]);}


            }if(size==0)
                {testStepPass("诊断故障码","诊断无故障");}
        }
      }
    else{
          for(i=0;i<size;i++)
             {
              if(DTCread[i]==DTC)
               {testStepPass("诊断故障码","获取到的故障码合法0x%06X",DTCread[i]);
                   //break;
                } else{ if(sate){}
                          else{testStepFail("诊断故障码","获取到的故障码不合法0x%06X",DTCread[i]);}

             }
       }
    for(i=0;i<size;i++)
       {
           if(DTCread[i]==DTC)
            {break;} 
       }if(i==size)
         {testStepFail("诊断故障码","故障码0x%06X未获取到",DTC);}
    }

  } 
}
