int TestStep_Read_Multi_DTC_InOrder (char Tstep[],dword expDTC[],byte expStatus[],byte isExpected, byte unique)
{
    byte subStepId;
    char tempText[255];
    char tempDTCStr[255],tempStatusStr[255];
    char signalName[100];
    int retVal,result;    
    long DTC_Num;
    int i ,j;
    dword ResDTC[100];
