/// <Bus>
_Signalinvalid(dword aId,int Cycle,signal *sig,int def, int sum,dword DTC)//信号有效位无效
{ 
  if(DTC)
  {  
    testEnableMsg(aId);
    Req14();//清故障
    testWaitForTimeout(1000);
    testStep("无效检测","信号有效位为%d无效%dms应不记录故障",1,Cycle*(sum-1));
    writeex(-3,0,"信号有效位为%d无效%dms应不记录故障",1,Cycle*(sum-1));
    setSignal(sig,def); //**********设置信号有效位无效
    _cntrset(aId,sum-1,Cycle);
    testResetSignalValue(sig);//**********
    testWaitForTimeout(Cycle);//等待
    TestStep_ReadDTC("诊断",DTC,9,0,0,1);//诊断故障,应无故障
    testWaitForTimeout(Cycle*sum*2);//等待

    Req14();
    testWaitForTimeout(Cycle*sum);//等待
    testStep("无效检测","信号有效位为%d无效%dms应记录故障",1,Cycle*(sum+1));
    writeex(-3,0,"信号有效位为%d无效%dms应记录故障",1,Cycle*(sum+1));
    setSignal(sig,def);//**********
    _cntrset(aId,sum+1,Cycle);
    testResetSignalValue(sig);//**********
    testWaitForTimeout(Cycle);//等待
    TestStep_ReadDTC("诊断",DTC,9,0,1,1);//**********  
  }
}
