      TestStep_ReadDTC("诊断",DTC,9,0,1,1);//**********
      testEnableMsg(msg);


    {
      byte index;
      byte num;
      byte Lack;
      byte FDF;
      _get_ID_Lack_FDF(msg,index,num,Lack,FDF);
      if(Lack == false )//此报文DLC-1不会干预到信号
      {
        if(less_unlack == true )//配置非预期DLC信号不缺失要报故障
