          testDisableMsg(msg);
          TestStep_ReadDTC("诊断",DTC,9,0,1,1);//**********
          testEnableMsg(msg);    
        }
        if(less_unlack == false )//配置非预期DLC信号不缺失 不报故障
        {        
          testWaitForTimeout(Cycle*sum*2);//等待
          Req14();          
          testStep("无效检测","长度为%d无效%dms应不记录故障",DLC-1,Cycle*(sum+1));
          writeex(-3,0,"UnexpectDlc:less&unlack 测试");
          writeex(-3,0,"长度为%d无效%dms应不记录故障",DLC-1,Cycle*(sum+1));
          putvalue(envar,DLC-1);//**********
          testWaitForTimeout(Cycle*(sum+1));
          testResetMsgDlc(msg);//**********
          ////testWaitForTimeout(Cycle);
          testDisableMsg(msg);
          TestStep_ReadDTC("诊断",DTC,9,0,0,1);//诊断故障,应无故障
          testEnableMsg(msg);    
        }        
      }
      if((FDF==CANframe && DLC<8)||(FDF==CANFDframe && DLC<15))
      {

        if(Greater == true )//配置大于DLC信号要报故障
        {        
          testWaitForTimeout(Cycle*sum*2);//等待
          Req14();          
          testStep("无效检测","长度为%d无效%dms应记录故障",DLC+1,Cycle*(sum+1));
          writeex(-3,0,"UnexpectDlc:Greater 测试");
          writeex(-3,0,"长度为%d无效%dms应记录故障",DLC+1,Cycle*(sum+1));
          putvalue(envar,DLC+1);//**********
          testWaitForTimeout(Cycle*(sum+1));
          putvalue(envar,DLC);//**********
          testDisableMsg(msg);
          TestStep_ReadDTC("诊断",DTC,9,0,1,1);//**********
          testEnableMsg(msg);    
        }
        if(Greater == false )//配置大于DLC信号不报故障
        {        
          testWaitForTimeout(Cycle*sum*2);//等待
          Req14();          
          testStep("无效检测","长度为%d无效%dms应不记录故障",DLC+1,Cycle*(sum+1));
          writeex(-3,0,"UnexpectDlc:Greater 测试");
          writeex(-3,0,"长度为%d无效%dms应不记录故障",DLC+1,Cycle*(sum+1));
          putvalue(envar,DLC+1);//**********
          testWaitForTimeout(Cycle*(sum+1));
          putvalue(envar,DLC);//**********
          testDisableMsg(msg);
          TestStep_ReadDTC("诊断",DTC,9,0,0,1);//诊断故障,应无故障
          testEnableMsg(msg);    
        }         

      }
    }


