Checkmsg(word aId,int Cycle,int dlc,long kTIMEOUT)
{ 
  float cycleoffset=0.1;
  dword gCycCheckId_cycle,gCycCheckId_dlc;
  float  MIN_CYCLE_TIME;
  float MAX_CYCLE_TIME;
  MIN_CYCLE_TIME = ((1-cycleoffset)*Cycle);
  MAX_CYCLE_TIME = ((1+cycleoffset)*Cycle);

  TestCaseTitle("ChecMsg", "检测EPS报文属性");
  testStep("","报文ID：0x%X",aId);
  gCycCheckId_cycle= ChkStart_MsgAbsCycleTimeViolation (aId,   // Message to supervise
                                    MIN_CYCLE_TIME,            // min-limit
                                    MAX_CYCLE_TIME);           // max-limit
  ///////////////////////////////////////////////////////////////
  gCycCheckId_dlc = ChkStart_InconsistentDLC(aId);
  TestAddCondition(gCycCheckId_dlc);
  ///////////////////////////////////////////////////////////////
  CheckMsgCyc(gCycCheckId_cycle,MIN_CYCLE_TIME, MAX_CYCLE_TIME,kTIMEOUT);
  ///////////////////////////////////////////////////////////////
  if(ChkQuery_NumEvents(gCycCheckId_dlc) > 0)
  {
      TestStepFail("ChecMsg","报文DLC异常%d次",ChkQuery_NumEvents(gCycCheckId_dlc));
   }else
  {
     TestSteppass("ChecMsg","报文DLC符合定义%d",dlc);
   }

  testRemoveCondition(gCycCheckId_cycle);
  TestRemoveCondition(gCycCheckId_dlc);


}

CheckMsgCyc(word aId,float aCycMinCycleTime, float aCycMaxCycleTime,long kTIMEOUT)
{ 
  long lQueryResultNumProbes;
  float lQueryResultProbeAvg;
  float lQueryResultProbeMin;
  float lQueryResultProbeMax;
  char lbuffer[100];

  TestAddCondition(aId);

  testWaitForTimeout(kTIMEOUT);

  lQueryResultNumProbes = /*ChkQuery_StatNumProbes*/ChkQuery_NumEvents(aId); 

  lQueryResultProbeAvg = ChkQuery_StatProbeIntervalAvg(aId);  
  lQueryResultProbeMin = ChkQuery_StatProbeIntervalMin(aId); 
  lQueryResultProbeMax = ChkQuery_StatProbeIntervalMax(aId);   

  if(ChkQuery_NumEvents(aId) > 0)
  {   snprintf(lbuffer,elcount(lbuffer),"周期有效区间 %.0fms - %.0fms", aCycMinCycleTime, aCycMaxCycleTime);      
      TestStepFail("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"平均周期时间:           %fms", lQueryResultProbeAvg);
      TestStepFail("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"最小周期时间:           %fms", lQueryResultProbeMin);
      TestStepFail("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"最大周期时间:           %fms", lQueryResultProbeMax);
      TestStepFail("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"异常次数:               %d次", lQueryResultNumProbes);
      TestStepFail("", lbuffer);

   }
   else
   {
      snprintf(lbuffer,elcount(lbuffer),"周期有效区间 %.0fms - %.0fms", aCycMinCycleTime, aCycMaxCycleTime);      
      TestStepPass("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"平均周期时间:           %fms", lQueryResultProbeAvg);
      TestStepPass("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"最小周期时间:           %fms", lQueryResultProbeMin);
      TestStepPass("", lbuffer);
      snprintf(lbuffer,elcount(lbuffer),"最大周期时间:           %fms", lQueryResultProbeMax);
      TestStepPass("", lbuffer);
  }
  ChkControl_Destroy(aId); // Destroy the check
}





/// <Check>
byte CRC8(byte da[],byte bytelbit[],int dataLength)
{  
  byte byte_index=0,bit_index=0,byte_i = 0;
  byte CRC=0;
  byte POLY;
  byte_index=0;
  bit_index=0;
  CRC=0xFF;
  POLY=0x1d;

  for(byte_index=0;byte_index<dataLength;byte_index++)
  {
    for ( byte_i = 0; byte_i < elcount(bytelbit); byte_i++)
    {
      if(bytelbit[byte_i]==byte_index) 
       { break;}
    }    
    if(byte_i==elcount(bytelbit))
    {

      CRC ^=da[byte_index];
    }    
    else
    {
      continue;
    } 
    for( bit_index=0; bit_index<8; ++bit_index )
    {
      if( (CRC & 0x80) > 0 )
      {
        CRC = (CRC << 1) ^ POLY;
      }
      else
        CRC = (CRC << 1);
    }
  }
  CRC^=0xFF;
  return CRC;
  }
/// <Check>
word CRC16(byte data[],byte bytelbit[],int dataLength) 
{
  int index;
  int bit=0;
  byte byte_index=0,byte_i = 0; 
  int c15=0;
  int i=0 ; 
  byte b=0;
  qword crc; // initial value
  qword  polynomial; // poly value
  polynomial = 0x1021;
  crc = 0xffff;
  for ( index = 0; index < dataLength; index++) 
  {

    for ( byte_i = 0; byte_i < elcount(bytelbit); byte_i++)
    {
      if(bytelbit[byte_i]==byte_index) 
       { break;}
    }    
    if(byte_i==elcount(bytelbit))
    {

      b = data[index];
    }      

       for ( i = 0; i < 8; i++) 
       {
             bit = ((b >> (7 - i) & 1) == 1);
             c15 = ((crc >> 15 & 1) == 1);
             crc <<= 1;
            if (c15 ^ bit)
           {crc ^= polynomial;}           
       }
  }
  crc &= 0xffff;
  return crc;
}
/// <Check>
byte CRC_Xor_FF(byte data[],byte bytelbit[],int dataLength) 
{
  int index;
  byte crc;
  crc=0;
  for ( index = 0; index < 8; index++) 
  {
    if((index) == bytelbit[0])
      {continue;}
    crc += data[index];
  }
  return crc^0xFF;
}
