}
/// <Check>
byte CRC_Checksum_XOR(byte data[],byte bytelbit[],int dataLength) 
{
  int index;
  byte crc;
  crc=0;
  for ( index = 0; index < 8; index++) 
  {
    if((index) == bytelbit[0])
      {continue;}
    crc ^= data[index];
  }
  return crc;
}
/// <Check>
byte CRC_Hig_xor_low(byte data[],byte bytelbit[],int dataLength) 
{
  int index,byte_i;
  byte crc;
  byte temp;
  temp=0;
  crc=0;
  byte_i=bytelbit[0] & 0xF;
  for ( index = 0; index < dataLength; index++) 
  {
    if(index == byte_i)
    {
      if( bytelbit[0] & 0xF0 == 0x80 )
      {
       temp =  (data[index] >> 4) & 0xF;
      }
      else{
        temp =  (data[index]) & 0xF;
      }
    }
    else{
      temp = ((data[index] >> 4) & 0xF) ^ (data[index] & 0xF);
    }

    crc ^= temp;

  }
  return crc & 0xF;
}
