    }
  }
  else
  {
    for (i = 0; i < elCount(RxMessageId); i++)
    {
      snprintf(envarName, elCount(envarName), "Switch_%X", RxMessageId[i]);
      if (RxMessageId[i] == msg)
      {
        putValue(envarName, 1);   // 目标报文：启用
      }
      else
      {
        putValue(envarName, 0);   // 其他报文：禁用
