/// <FUN>
diagSendReq(byte code[])
{
  int i;
  char Code[100];
  diagRequest * req;
  snprintf(Code,elCount(Code),"");
  diagSetTarget("ABS_ESP");
  diagResize(req,elcount(code));
  for(i=0;i<elcount(code);i++)
  {
    DiagSetPrimitiveByte(req,i,code[i]);
  }
  diagSendRequest(req);
  testWaitForDiagRequestSent(req,100);
  testWaitForDiagResponse(req,500);
  if(DiagGetRespPrimitiveByte(req,0)==0x7f)
  {   
    for(i=0;i<(DiagGetRespPrimitiveSize(req));i++)
      { 
        snprintf(Code,elCount(Code),"%s%02X ",Code,DiagGetRespPrimitiveByte(req,i));
      }
    testStepFail("诊断负响应","响应码 %s",Code);
  }
  else{
    testSteppass("诊断正响应","诊断正响应");
  }
  diagStopTesterPresent();
}
/// <FUN>
void VoltSet(float Value)
{
  @sysvar::Prog_power::K30Volt=Value;
}
void Battery_Voltage_GreaterSet(sysvarFloat *Var,float Value)
{
  float Volt,currentVolt;
  xcpSetPollingCycle(Var,10);
  Volt=@sysvar::Prog_power::K30Volt;  
  while(1)
  { currentVolt=getxcp(Var);
    if(((Value+0.03) < currentVolt) && (currentVolt < (Value+0.07)))
    {break;}
    else
    {
      Volt+=((Value+0.05)-(currentVolt))/2;

      if(Volt>26 || Volt<0)
        {break;}
      VoltSet(Volt);
      testWaitForTimeout(100);
    }
  }
  writeex(-3,0,"电压设置 %gV",getxcp(Var));
  testStep("电压设置","电压--%g V",getxcp(Var));

}
void Battery_Voltage_lessSet(sysvarFloat *Var,float Value)
{
  float Volt,currentVolt;
  Volt=@sysvar::Prog_power::K30Volt; 
  xcpSetPollingCycle(Var,10);
  while(1)
  { currentVolt=getxcp(Var);
    if(Value-0.07 < currentVolt && currentVolt < Value-0.03)
    {break;}
    else
    {
      Volt+=((Value-0.05)-(currentVolt))/2;
      if(Volt>26 || Volt<0)
        {break;}    
      VoltSet(Volt);
      testWaitForTimeout(100);
    }
  }
  writeex(-3,0,"电压设置 %gV",getxcp(Var));
  testStep("电压设置","电压--%g V",getxcp(Var));
}
