/// <Check>
SignalRowCheck(signal * sig, word compareValue)
{

  long result;

  result = (getRawSignal(sig) == compareValue);  
  snprintf(SigName,elcount(SigName),"%s",sig.name);
  snprintf(ExpectHear,elcount(ExpectHear),"Expect");
  snprintf(ExpectValue,elcount(ExpectValue),"%X",compareValue);
  snprintf(ResultValue,elcount(ResultValue),"%X",getRawSignal(sig));  
  switch(result)
  {
    case (1):SignalCheck_addTable(SigName,ExpectHear,ExpectValue,ResultValue,"pass");break;
    case (0):SignalCheck_addTable(SigName,ExpectHear,ExpectValue,ResultValue,"fail");break;
  }

}
/// <Check>
SignalWaitCheck(signal * sig, float compareValue)
{

  long result;
  result = testWaitForSignalMatch(sig, compareValue,1000);  
  snprintf(SigName,elcount(SigName),"%s",sig.name);
  snprintf(ExpectHear,elcount(ExpectHear),"Expect");
  snprintf(ExpectValue,elcount(ExpectValue),"%g",compareValue);
