/// <Diag>
_testDTC(dword DTC,byte diag,byte sate)//单故障码诊断  diag:1-当前故障；9-历史故障,sate：1-查询有无DTC；0-查询是否只有DTC
{
  diagRequest  *  req1902;
  diagSetTarget ("ABS_ESP");

  // 这样些可以不依赖dbc文件的定义，方便平台共用，也可以使用dbc中定义的诊断名称
  diagResize(req1902,3);
  DiagSetPrimitiveByte(req1902,0,0x19);
  DiagSetPrimitiveByte(req1902,1,0x02);
  DiagsetPrimitiveByte(req1902,2,diag);
  diagSendRequest(req1902);
  testReportWriteDiagObject(req1902);
  testWaitForDiagResponse(req1902,5000);
  testReportWriteDiagResponse(req1902);
  if(diagGetLastResponseCode(req1902)==-1)
  { 
    byte j;
    byte i;
    byte size;
    dword DTCread[100];
    dword buffer[300];
    size=DiagGetRespPrimitiveSize(req1902);
    for(i=0;i<(size-3);i++)
    {
      buffer[i]=DiagGetRespPrimitiveByte(req1902,i+3);
    }
    size=(size-3)/4;

    for(i=0;i<size;i++)
    {
      DTCread[i]=(buffer[i*4]<<16)|(buffer[i*4+1]<<8)|buffer[i*4+2];
    }
    if((DTC==0))
      {
        if(size>0)
        {testStepFail("诊断故障码","获取到的故障码不合法");}
        if(!sate)
        {
          for(i=0;i<size;i++)
           {
           if(DTCread[i]==DTC)
            {
             } else{testStepFail("诊断故障码","获取到的故障码不合法0x%06X",DTCread[i]);}


            }if(size==0)
                {testStepPass("诊断故障码","诊断无故障");}
        }
      }
    else{
          for(i=0;i<size;i++)
             {
              if(DTCread[i]==DTC)
               {testStepPass("诊断故障码","获取到的故障码合法0x%06X",DTCread[i]);
                   //break;
                } else{ if(sate){}
                          else{testStepFail("诊断故障码","获取到的故障码不合法0x%06X",DTCread[i]);}

             }
       }
    for(i=0;i<size;i++)
       {
           if(DTCread[i]==DTC)
            {break;} 
       }if(i==size)
         {testStepFail("诊断故障码","故障码0x%06X未获取到",DTC);}
    }

  } 
}
