CommunicationVoltage_Rise(float Volt,float DelayVolt,long  Time,sysvarFloat *Var)
{
  VoltSet(12);
  testWaitForTimeout(1000);
  testWaitForSysVar(Var,1000);
  writeex(-3,0,"通信电压高压--未成熟");
  testStep("通信电压","通信电压高压--未成熟");
  Battery_Voltage_lessSet(Var,Volt); 
  if(Time) 
  testWaitForTimeout(Time);
  CheckTx(1);

  writeex(-3,0,"通信电压高压--成熟");
  testStep("通信电压","通信电压高压--成熟");
  Battery_Voltage_GreaterSet(Var,Volt);  
  if(Time)   
  testWaitForTimeout(Time);
  CheckTx(0);

  writeex(-3,0,"通信电压高压恢复--未恢复");
  testStep("通信电压","通信电压高压恢复--未恢复");  
  Battery_Voltage_GreaterSet(Var,Volt-DelayVolt);   
  if(Time)   
  testWaitForTimeout(Time);
  CheckTx(0);


  writeex(-3,0,"通信电压高压恢复--恢复");
  testStep("通信电压","通信电压高压恢复--恢复");
  Battery_Voltage_lessSet(Var,Volt-DelayVolt);   
  if(Time)   
  testWaitForTimeout(Time);
  CheckTx(1);
  {
    float Higvolt;
    Higvolt=20;
    IGoFF();
    VoltSet(Higvolt);
    testWaitForTimeout(1000);
    IGoN();
    testWaitForTimeout(2000);    
    while(1)
    { Higvolt-=0.1; 
      if(TestGetVerdictLastTestCase()==1 || (Volt-DelayVolt)+0.1>=Higvolt)
      { 
        writeex(-3,0,"%f   %f",(Volt+DelayVolt),Higvolt);
        break; 
      }
      Battery_Voltage_lessSet(Var,Higvolt); 
      testWaitForTimeout(1000);
      CheckTx(0);       
    }
    if(TestGetVerdictLastTestCase()==1)
    { 
      writeex(-3,0,"通信电压超高压恢复--恢复 %f",Higvolt);
      testStepFail("通信电压","通信电压超高压恢复--恢复");      
    }
    else
    {
      Battery_Voltage_lessSet(Var,Volt-DelayVolt);  
      if(Time)   
      testWaitForTimeout(Time);
      CheckTx(1); 
      if(TestGetVerdictLastTestCase()==1)
      { 
        writeex(-3,0,"通信电压超高压恢复--恢复 %f",Higvolt);
        testSteppass("通信电压","通信电压超高压恢复--恢复");      
      }      
    }    
  }

  VoltSet(12);
}
