void RelayON(byte Ctr_state)
{
  if(RelayMode==3)
  {
  Relaymsg.can=RelayCAN;
  Relaymsg.id=0x101;
  switch(Ctr_state)
  {
    case 1:RelayState&=0xFE;break;
