    case 3:RelayState&=0xFB;break;
    case 4:RelayState&=0xF7;break;
    case 5:RelayState&=0xEF;break;
    case 6:RelayState&=0xDF;break;
    case 7:RelayState&=0xBF;break;
    case 8:RelayState&=0x7F;break;
  }
  Relaymsg.byte(0)=RelayState;
  output(Relaymsg);
  }
  if(RelayMode==2)
