    case 8:RelayState|=0x80;break;
  }
  Relaymsg.byte(0)=RelayState;
  output(Relaymsg);
  }  
  if(RelayMode==1)
  {
    if(Ctr_state==1)
    {
      _outIGon();
    }

  }
}
